mapper.select:
SELECT d.id, d.couple_id, d.user_id, d.diary_date, d.mood, d.content, d.images,
       d.created_at, d.updated_at, u.nickname AS author
FROM diary d
LEFT JOIN user u ON d.user_id = u.id
WHERE d.couple_id = #{coupleId}

    AND d.mood = #{mood}

ORDER BY d.diary_date DESC, d.created_at DESC
LIMIT #{offset}, #{size}

mapper.update:
UPDATE diary
SET diary_date = #{diaryDate}, mood = #{mood}, content = #{content}, images = #{images}
WHERE id = #{id} AND user_id = #{userId}
